\set ON_ERROR_STOP on
-- Website products already reviewed on 2026-11-12. Idempotent: rows that exist are left alone.
-- Applied inside a single transaction by the release script (psql -1).
ON CONFLICT (website_product_id) DO NOTHING;
DO $$ BEGIN
  IF (SELECT COUNT(*) FROM website_products WHERE status = 'imported' AND product_id IS NULL) > 0 THEN
    RAISE EXCEPTION 'An imported website product could not be linked to its POS product';
  END IF;
END $$;
